await forView('/pools', async () => {
  // The attention poll is one per page load and keeps its last list through a failed read, so a first read that fails
  // can only be met here, before any page has read the conditions.
  const { getAttention } = api;
  const failing = () => Promise.reject(new Error('the store is unavailable'));
  api.getAttention = failing;
  const held = deferNextCall('listPools');
  const p = await mount('/pools');
  const line = () => p.container.querySelector('.attention-line');
  const unavailable = () => line()?.textContent?.trim() === 'Attention unavailable: the store is unavailable' && line()?.nextElementSibling?.classList.contains('pool-grid') === true;
  const rows = () => JSON.stringify([...p.container.querySelectorAll('.pool')].map((c) => c.querySelectorAll('ul.attention > li.attention__row').length));
  const loading = [unavailable(), p.container.querySelectorAll('.pool').length];
  held.release();
  held.restore();
  await p.settle(300);
  results.push({
    name: '/pools a first attention read that fails draws the unavailable line above the grid, while the pools load and over cards without a badge',
    ok: loading[0] === true && loading[1] === 0 && unavailable() && rows() === '[0,0,0,0,0,0]',
    missing: [JSON.stringify(loading), line()?.outerHTML.slice(0, 200) ?? 'no line', rows()],
  });
  api.getAttention = getAttention;
  window.dispatchEvent(new window.Event('focus'));
  await p.settle(300);
  const healthy = [line() === null, rows()];
  api.getAttention = failing;
  window.dispatchEvent(new window.Event('focus'));
  await p.settle(300);
  api.getAttention = getAttention;
  results.push({
    name: "/pools a refresh that fails after a read answered draws the unavailable line and the cards keep the last read's badges",
    ok: healthy[0] === true && healthy[1] !== '[0,0,0]' && unavailable() && rows() === healthy[1],
    missing: [...healthy.map(String), line()?.outerHTML.slice(0, 200) ?? 'no line', rows()],
  });
  window.dispatchEvent(new window.Event('focus'));
  await p.settle(300);
  p.unmount();
});

await forView('/', async () => {
  localStorage.removeItem('phoebis.mockSession');
  const login = await mount('/');
  expect('login screen without a session', login.text(), ['Admin secret', 'Log in']);
  // The mark sets its paints as attributes, read here one by one, so a mark that draws nothing fails the check, and so
  // does a shape or a gradient stop the theme toggle would not reach: a fixed color, no paint at all (black), or a token
  // that the light or the dark block of tokens.css leaves undeclared, which paints black or one color in both themes.
  const mark = login.container.querySelector('.brand__mark svg');
  const inside = mark ? [mark, ...mark.querySelectorAll('*')] : [];
  const css = [...readFileSync(new URL('../src/styles/tokens.css', import.meta.url), 'utf8').replace(/\/\*[\s\S]*?\*\//g, '').matchAll(/([^{}]+)\{([^{}]*)\}/g)];
  const blocks = [':root', ":root[data-theme='dark']"].map((head) => [head, css.filter(([, h]) => h.trim() === head).flatMap(([, , body]) => [...body.matchAll(/(--[\w-]+)\s*:/g)].map((d) => d[1]))]);
  const gradients = new Set(inside.filter((el) => /^(linear|radial)Gradient$/.test(el.tagName) && el.querySelector('stop') !== null).map((el) => el.id));
  const shapes = inside.filter((el) => ['circle', 'ellipse', 'line', 'path', 'polygon', 'polyline', 'rect'].includes(el.tagName));
  const fixed = inside.flatMap((el) => ['fill', 'stroke', 'stop-color'].flatMap((prop) => {
    const paint = el.getAttribute(prop);
    if (paint === null) return (prop === 'fill' && shapes.includes(el)) || (prop === 'stop-color' && el.tagName === 'stop') ? [`${el.tagName} with no ${prop}`] : [];
    if (paint === 'none' || gradients.has(/^url\(#(.+)\)$/.exec(paint)?.[1])) return [];
    const token = /^var\((--[\w-]+)\)$/.exec(paint)?.[1];
    return token ? blocks.filter(([, names]) => !names.includes(token)).map(([head]) => `${token} missing from ${head}`) : [`${el.tagName} ${prop} ${paint}`];
  }));
  const draws = shapes.some((el) => el.getAttribute('fill') !== 'none' || (el.getAttribute('stroke') ?? 'none') !== 'none');
  results.push({ name: 'the login view carries the mark, drawn in the theme tokens alone, and the couplet', ok: draws && fixed.length === 0 && login.text().includes('Place every request. Keep every session.'), missing: [draws ? 'the mark draws' : 'the mark draws nothing', ...fixed] });
  const stay = login.container.querySelector('.login__card input[type="checkbox"]');
  const stayField = stay?.closest('.field') ?? null;
  // Read off the label that wraps the box, so a click on the words ticks it.
  const stayLabel = stay?.closest('label')?.querySelector('.field__label')?.textContent ?? '';
  const stayHint = stayField?.querySelector('.field__hint')?.textContent ?? '';
  const underSecret = login.container.querySelector('input[type="password"]')?.closest('.field')?.nextElementSibling === stayField;
  results.push({
    name: 'the login screen draws "Stay logged in" unchecked under the secret field, with its hint',
    ok: stay !== null && !stay.checked && stayLabel === 'Stay logged in' && underSecret && stayHint === 'Keeps this browser logged in for 30 days, renewed on every visit. A secret rotation ends it earlier.',
    missing: [stay ? (stay.checked ? 'checked' : 'unchecked') : 'no checkbox', stayLabel || 'no label', underSecret ? 'under the secret field' : 'not under the secret field', stayHint || 'no hint'],
  });
  const unchecked = countCalls('login');
  const input = login.container.querySelector('input[type="password"]');
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  setter.call(input, 'admin');
  input.dispatchEvent(new window.Event('input', { bubbles: true }));
  [...login.container.querySelectorAll('button')].find((b) => b.textContent?.trim() === 'Log in')?.click();
  // The dashboard draws on its own turns, so each step waits for the screen it leads to rather than a fixed delay.
  await until(login, () => login.text().includes('Requests, 24h'));
  unchecked.restore();
  const plainSession = await api.getSession();
  results.push({
    name: 'a login with "Stay logged in" unchecked sends it false and the mock answers a session that is not kept',
    ok: JSON.stringify(unchecked.calls) === JSON.stringify([['admin', false]]) && plainSession?.persistent === false,
    missing: [JSON.stringify(unchecked.calls), JSON.stringify(plainSession)],
  });
  // The bar must exist, or a renamed class would pass the count by matching nothing.
  const topbarRight = login.container.querySelector('.topbar__right');
  const topbarBadges = login.container.querySelectorAll('.topbar__right .badge').length;
  results.push({ name: 'a login lands on the dashboard with no badge in the top bar', ok: login.text().includes('Requests, 24h') && topbarRight !== null && topbarBadges === 0 && !login.text().includes('Log in'), missing: [`top bar ${topbarRight === null ? 'absent' : 'drawn'}`, `top bar badges ${topbarBadges}`] });
  [...login.container.querySelectorAll('button')].find((b) => b.getAttribute('aria-label') === 'Log out')?.click();
  await until(login, () => login.text().includes('Admin secret'));
  results.push({ name: 'Log out returns to the login screen', ok: login.text().includes('Admin secret'), missing: [] });
  const checked = countCalls('login');
  login.container.querySelector('.login__card input[type="checkbox"]')?.click();
  const again = login.container.querySelector('input[type="password"]');
  setter.call(again, 'admin');
  again.dispatchEvent(new window.Event('input', { bubbles: true }));
  [...login.container.querySelectorAll('button')].find((b) => b.textContent?.trim() === 'Log in')?.click();
  await until(login, () => login.text().includes('Requests, 24h'));
  checked.restore();
  const keptSession = await api.getSession();
  results.push({
    name: 'a login with "Stay logged in" checked sends it true and the mock answers a kept session',
    ok: JSON.stringify(checked.calls) === JSON.stringify([['admin', true]]) && keptSession?.persistent === true,
    missing: [JSON.stringify(checked.calls), JSON.stringify(keptSession)],
  });
  // Signed out again, so the blocks below find the mock's session as the block found it.
  [...login.container.querySelectorAll('button')].find((b) => b.getAttribute('aria-label') === 'Log out')?.click();
  const signedOut = await until(login, () => login.text().includes('Admin secret'));
  results.push({ name: "the login block's closing Log out returns to the login screen", ok: signedOut, missing: [] });
  login.unmount();
  localStorage.setItem('phoebis.mockSession', 'admin');
});

