    return { ...answer, accounts: answer.accounts.map((a) => (a.accountId === 'sunset' ? { ...a, windows: a.windows.map((w) => ({ ...w, resets: w.resets.map((r, i) => (i === 0 ? { ...r, plan: null, tier: null } : r)) })) } : a)) };
