    const handle = () => dlg?.querySelector('[role="slider"][aria-label="5-hour ceiling"]');
    const ceiling = () => dlg?.querySelector('input[aria-label="5-hour ceiling (%)"]')?.value ?? 'absent';
    const steps = [];
