    const read = () => [handle()?.getAttribute('aria-valuenow'), handle()?.getAttribute('aria-valuemin'), handle()?.getAttribute('aria-valuemax'), handle()?.style.left, handle()?.getAttribute('aria-valuetext')];
    const past = read();
