    const want = ultra === undefined ? null : [...TYPES.map(() => ''), ...TYPES.map((t) => fmtShare(shareIn(regimeCosts, 'seven_day_fable', ultra, 'claude-fable-5-1', usage(t, 1_000_000), inBand(regimeCosts, OUT))))];
